const TEAMS = [
  { name: "Platform", count: 8 },
  { name: "Design", count: 5 },
  { name: "Marketing", count: 4 },
];

export function TeamList({
  title = "{{title}}",
  color = "{{color}}",
  density = "{{density}}",
  showCount = {{showCount}},
}) {
  const pad = density === "compact" ? "5px 4px" : "10px 4px";
  return (
    <section style={{ font: "14px/1.4 system-ui, sans-serif", color: "#241430", maxWidth: 300 }}>
      <h3 style={{ margin: "0 0 8px", fontSize: 16 }}>{title}</h3>
      <ul style={{ listStyle: "none", margin: 0, padding: 0, borderTop: "1px solid #24143018" }}>
        {TEAMS.map((team) => (
          <li key={team.name} style={{ display: "flex", justifyContent: "space-between", alignItems: "center", padding: pad, paddingLeft: 10, borderBottom: "1px solid #24143018", borderLeft: `3px solid ${color}` }}>
            <span>{team.name}</span>
            {showCount && <span style={{ fontSize: 12, opacity: 0.7 }}>{team.count} members</span>}
          </li>
        ))}
      </ul>
    </section>
  );
}
